 /** 0.1.112：离开详情页时收起右上角「收藏 / 下载」，服务器列表、媒体库等页面不显示。 */
 void clearExtras(){try{LinearLayout header=(LinearLayout)root.getChildAt(0);for(int i=header.getChildCount()-1;i>=0;i--){Object tag=header.getChildAt(i).getTag();if("mp-fav".equals(tag)||"mp-dl".equals(tag))header.removeViewAt(i);}}catch(Exception ignored){}}
 void screen(String label){PosterDetail.restore(this,body,card(),light);DetailLandscape.unsplit(body);clearExtras();epoch++;watch.removeCallbacksAndMessages(null);if(pending!=null)pending.cancel(true);body.removeAllViews();poster=null;episodeStrip=null;detailArt=null;fusionEpisodeArt=false;status.setVisibility(View.VISIBLE);status.setText(label);}
 void work(String label,Work task,Runnable retry){work(label,task,retry,WORK_LIMIT);}
 void work(String label,Work task,Runnable retry,int limit){int token=++epoch;watch.removeCallbacksAndMessages(null);if(pending!=null)pending.cancel(true);status.setText(label);skeleton(label);
  // 0.1.103：每个任务单独一条线程（原来单线程排队，前一个磁力解析卡住时后面的详情页永远轮不到，一直停在「正在读取…」）；
  // 只认最新一次 epoch 的结果；超过 WORK_LIMIT 还没回来就判超时，给出「重试」，迟到的结果直接丢弃。Error 也算失败，不会让状态行停住。
  Runnable timeout=()->{if(dead||token!=epoch)return;epoch++;if(pending!=null)pending.cancel(true);Skeleton.clear(body);status.setText(label.replace("…","")+"超时（"+limit/1000+" 秒未返回）");row("重试",retry);};watch.postDelayed(timeout,limit);
  status.setVisibility(View.VISIBLE);
  pending=io.submit(()->{try{Runnable done=task.run();runOnUiThread(()->{watch.removeCallbacks(timeout);if(!dead&&token==epoch){status.setText("");Skeleton.clear(body);try{done.run();}catch(RuntimeException e){status.setVisibility(View.VISIBLE);status.setText("页面显示失败："+why(e));row("重试",retry);}}});}catch(Throwable e){runOnUiThread(()->{watch.removeCallbacks(timeout);if(dead||token!=epoch)return;Skeleton.clear(body);status.setVisibility(View.VISIBLE);status.setText("读取失败："+why(e));row("重试",retry);});}});}
 /** 0.1.123：按读取的内容放加载骨架（详情页 / 海报网格），结果回来或失败时清掉。 */
 void skeleton(String label){Skeleton.clear(body);int w=body.getWidth()>0?body.getWidth()-body.getPaddingLeft()-body.getPaddingRight():getResources().getDisplayMetrics().widthPixels-dp(32);
  if(label.contains("详情")||label.contains("选集"))body.addView(Skeleton.detail(this,card(),Math.min(dp(360),(int)(getResources().getDisplayMetrics().widthPixels*.62f))));
  else if(label.contains("条目")||label.contains("分类")||label.contains("搜索"))body.addView(Skeleton.grid(this,card(),w,3));}
 static final int WORK_LIMIT=45000;
 static String why(Throwable e){return e.getMessage()==null?e.getClass().getSimpleName():e.getMessage();}
 void push(Runnable destination,Runnable previous){back.push(previous);destination.run();}
 void home(){screen(session.site.optString("name"));work("正在读取分类…",()->{JSONObject response=FusionCatalog.request(this,session,"home","","",1);return ()->{status.setText(session.site.optString("name")+" · "+state());JSONArray cats=response.optJSONArray("class");if(cats!=null)for(int i=0;i<cats.length();i++){JSONObject c=cats.optJSONObject(i);if(c!=null)row(c.optString("type_name","分类"),()->push(()->category(c.optString("type_id"),1),()->home()));}gallery(response.optJSONArray("list"),()->home());};},()->home());}
 String state(){if(CmsApi.MARKER.equals(session.site.optString("api")))return session.site.optString("public.status","此公开源待本机实播验证");return session.site.optString("api").equals("csp_AListSh")?"小雅样本已验证播放":"此线路尚未完成实播验证";}
 void category(String id,int page){screen(session.site.optString("name"));work("正在读取分类 · 第 "+page+" 页…",()->{JSONObject response=FusionCatalog.request(this,session,"category",id,"",page);return ()->{status.setText(session.site.optString("name")+" · 第 "+page+" 页");gallery(response.optJSONArray("list"),()->category(id,page));if(response.optInt("pagecount",page)>page)row("下一页",()->push(()->category(id,page+1),()->category(id,page)));};},()->category(id,page));}
